INSERT INTO public.hh_ideas_aphorisms
  (id,topic,keywords,text_en,text_ru,text_es,kind,source_author,source_work,source_url)
VALUES
  ('hh-relationships-01','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'Friendship strengthens when truth can be spoken gently.','Дружба крепнет там, где правду можно говорить бережно.','La amistad se fortalece cuando la verdad puede decirse con delicadeza.','inspired','Ralph Waldo Emerson','Essays, First Series (1841)','https://www.gutenberg.org/ebooks/2944'),
  ('hh-relationships-02','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'An honest question opens more doors than a polished accusation.','Честный вопрос открывает больше дверей, чем изящное обвинение.','Una pregunta sincera abre más puertas que una acusación elegante.','editorial',NULL,NULL,NULL),
  ('hh-relationships-03','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'Listening is an act of hospitality toward another person''s world.','Слушать — значит гостеприимно впускать в себя чужой мир.','Escuchar es ofrecer hospitalidad al mundo de otra persona.','editorial',NULL,NULL,NULL),
  ('hh-relationships-04','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'A disagreement need not become a verdict on the whole relationship.','Разногласие не обязано становиться приговором всей связи.','Un desacuerdo no tiene por qué condenar toda la relación.','editorial',NULL,NULL,NULL),
  ('hh-relationships-05','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'The strongest bond leaves space for two separate hearts.','Прочная связь оставляет пространство для двух разных сердец.','Un vínculo sólido deja espacio para dos corazones distintos.','editorial',NULL,NULL,NULL),
  ('hh-relationships-06','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'Trust grows through small repeated acts, not grand assurances.','Доверие вырастает из маленьких повторяющихся поступков, а не из громких заверений.','La confianza crece con actos pequeños y constantes, no con grandes promesas.','editorial',NULL,NULL,NULL),
  ('hh-relationships-07','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'To repair a bond, begin with what you can truly acknowledge.','Чтобы восстановить связь, начни с того, что можешь искренне признать.','Para reparar un vínculo, empieza por aquello que puedes reconocer sinceramente.','editorial',NULL,NULL,NULL),
  ('hh-relationships-08','relationships',ARRAY['отношен','близост','партнер','друж','довер','конфликт','relationship','partner','friend','trust','conflict','relacion','pareja','amistad','confianza']::text[],'A close conversation is not a contest with a winner.','Разговор близких — не соревнование, в котором нужен победитель.','Una conversación íntima no es una competición que necesite ganador.','editorial',NULL,NULL,NULL),
  ('hh-stress-01','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'What lies beyond your control need not rule your inner weather.','То, что не в твоей власти, не обязано управлять твоей внутренней погодой.','Lo que escapa a tu control no tiene por qué gobernar tu clima interior.','inspired','Epictetus','The Enchiridion (George Long, public-domain translation)','https://www.gutenberg.org/ebooks/10661'),
  ('hh-stress-02','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'Fear becomes louder when every thought is treated as a prediction.','Страх звучит громче, когда каждую мысль принимают за предсказание.','El miedo se hace más fuerte cuando tomamos cada pensamiento como una predicción.','editorial',NULL,NULL,NULL),
  ('hh-stress-03','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'A quiet pause can be a form of courage, not a retreat.','Тихая пауза может быть проявлением мужества, а не отступлением.','Una pausa tranquila puede ser un acto de valentía y no una retirada.','editorial',NULL,NULL,NULL),
  ('hh-stress-04','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'You can feel unsettled and still choose one kind action.','Можно чувствовать тревогу и всё же выбрать один добрый поступок.','Puedes sentir inquietud y aun así elegir un acto amable.','editorial',NULL,NULL,NULL),
  ('hh-stress-05','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'The next breath is a moment, not an examination you must pass.','Следующий вдох — это мгновение, а не экзамен, который нужно сдать.','La siguiente respiración es un instante, no un examen que debas aprobar.','editorial',NULL,NULL,NULL),
  ('hh-stress-06','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'Not every urgent feeling requires an urgent decision.','Не каждое неотложное чувство требует немедленного решения.','No toda emoción urgente exige una decisión inmediata.','editorial',NULL,NULL,NULL),
  ('hh-stress-07','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'Relief may begin when you stop arguing with the fact that you feel afraid.','Облегчение иногда начинается, когда перестаёшь спорить с фактом своего страха.','El alivio puede empezar cuando dejas de discutir con el hecho de sentir miedo.','editorial',NULL,NULL,NULL),
  ('hh-stress-08','stress',ARRAY['тревог','страх','стресс','паник','стыд','напряж','anxiety','stress','fear','panic','worry','ansiedad','miedo','panico','preocupacion']::text[],'Give your attention to the next safe step, not to every imagined ending.','Направь внимание на ближайший безопасный шаг, а не на все воображаемые исходы.','Pon tu atención en el siguiente paso seguro, no en todos los finales imaginados.','editorial',NULL,NULL,NULL),
  ('hh-resources-01','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'A simpler day can leave more room for a fuller life.','Более простой день порой оставляет больше места для полноценной жизни.','Un día más sencillo puede dejar más espacio para una vida plena.','inspired','Henry David Thoreau','Walden (1854)','https://www.gutenberg.org/ebooks/205'),
  ('hh-resources-02','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'A candle is not selfish for needing wax.','Свече не нужно оправдываться за то, что ей необходим воск.','Una vela no es egoísta por necesitar cera.','editorial',NULL,NULL,NULL),
  ('hh-resources-03','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'Rest belongs inside the journey, not at its distant finish.','Отдых — часть пути, а не награда где-то у финиша.','El descanso forma parte del camino, no espera al final lejano.','editorial',NULL,NULL,NULL),
  ('hh-resources-04','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'Your pace is allowed to change without changing your worth.','Твой темп может меняться, не меняя твоей ценности.','Tu ritmo puede cambiar sin que cambie tu valor.','editorial',NULL,NULL,NULL),
  ('hh-resources-05','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'When energy is scarce, protect the essential before adding more.','Когда сил мало, сначала защити главное, а потом добавляй новое.','Cuando falta energía, protege lo esencial antes de añadir más.','editorial',NULL,NULL,NULL),
  ('hh-resources-06','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'A reliable small habit is a quiet kind of strength.','Небольшая устойчивая привычка — тихая разновидность силы.','Un hábito pequeño y constante es una forma silenciosa de fuerza.','editorial',NULL,NULL,NULL),
  ('hh-resources-07','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'You do not replenish a garden by demanding more flowers.','Сад не восстановить, требуя от него всё новых цветов.','No recuperas un jardín exigiéndole más flores.','editorial',NULL,NULL,NULL),
  ('hh-resources-08','resources',ARRAY['устал','энерг','ресурс','выгор','истощ','сил','отдых','сон','tired','energy','exhausted','burnout','rest','sleep','cansado','energia','agotado','descanso','sueno']::text[],'The body often asks for rhythm before it asks for ambition.','Тело нередко просит ритма раньше, чем новых свершений.','El cuerpo suele pedir ritmo antes que nuevas ambiciones.','editorial',NULL,NULL,NULL),
  ('hh-work-01','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'Guard your working hours; no fortune can return a wasted day.','Береги часы своего труда: никакое состояние не вернёт потраченный день.','Cuida tus horas de trabajo: ninguna fortuna devolverá un día perdido.','inspired','Seneca','Moral Letters to Lucilius','https://senecaletters.com/en/about'),
  ('hh-work-02','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'Busy is not always the same as useful.','Быть занятым не всегда значит делать полезное.','Estar ocupado no siempre significa hacer algo útil.','editorial',NULL,NULL,NULL),
  ('hh-work-03','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'Before climbing faster, ask whether the ladder faces your mountain.','Прежде чем подниматься быстрее, проверь, к твоей ли вершине приставлена лестница.','Antes de subir más rápido, mira si la escalera apunta a tu montaña.','editorial',NULL,NULL,NULL),
  ('hh-work-04','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'A good decision can protect your peace as well as your income.','Хорошее решение может беречь не только доход, но и покой.','Una buena decisión puede proteger tanto tus ingresos como tu calma.','editorial',NULL,NULL,NULL),
  ('hh-work-05','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'A clear promise is worth more than ten vague possibilities.','Ясное обещание дороже десяти туманных возможностей.','Una promesa clara vale más que diez posibilidades vagas.','editorial',NULL,NULL,NULL),
  ('hh-work-06','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'The work that matters deserves intervals of undivided attention.','Важное дело заслуживает времени, когда внимание принадлежит только ему.','El trabajo importante merece momentos de atención sin divisiones.','editorial',NULL,NULL,NULL),
  ('hh-work-07','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'A fair boundary at work protects the quality of your yes.','Честная граница в работе защищает качество твоего «да».','Un límite justo en el trabajo protege el valor de tu sí.','editorial',NULL,NULL,NULL),
  ('hh-work-08','work',ARRAY['работ','карьер','бизнес','деньги','доход','проект','зарплат','work','career','business','income','salary','job','trabajo','negocio','ingreso','dinero','empleo']::text[],'Do not confuse the price of your work with the worth of your life.','Не путай цену своей работы с ценностью своей жизни.','No confundas el precio de tu trabajo con el valor de tu vida.','editorial',NULL,NULL,NULL),
  ('hh-direction-01','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'A long road asks first for one step on the ground before you.','Долгий путь сначала просит одного шага по земле перед тобой.','Un camino largo pide primero un paso sobre la tierra que tienes delante.','inspired','Laozi','Tao Te Ching (James Legge, 1891)','https://www.gutenberg.org/ebooks/216'),
  ('hh-direction-02','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'A crossroads is a place to notice your values, not only your options.','Перекрёсток нужен, чтобы увидеть не только варианты, но и свои ценности.','Una encrucijada sirve para ver no solo opciones, sino también tus valores.','editorial',NULL,NULL,NULL),
  ('hh-direction-03','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'Uncertainty is a landscape; it does not have to be a prison.','Неопределённость — это ландшафт, а не обязательно тюрьма.','La incertidumbre es un paisaje; no tiene por qué ser una prisión.','editorial',NULL,NULL,NULL),
  ('hh-direction-04','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'You can revise a route without betraying the traveler you once were.','Можно изменить маршрут, не предавая себя прежнего.','Puedes cambiar de ruta sin traicionar a quien fuiste.','editorial',NULL,NULL,NULL),
  ('hh-direction-05','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'Sometimes the smaller choice reveals the larger truth.','Иногда маленький выбор открывает большую истину.','A veces una elección pequeña revela una verdad mayor.','editorial',NULL,NULL,NULL),
  ('hh-direction-06','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'Clarity is often discovered while moving, not before moving.','Ясность нередко приходит во время движения, а не до него.','La claridad suele descubrirse mientras avanzas, no antes.','editorial',NULL,NULL,NULL),
  ('hh-direction-07','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'The right question may be more useful than a hurried answer.','Правильный вопрос порой полезнее поспешного ответа.','La pregunta adecuada puede servir más que una respuesta apresurada.','editorial',NULL,NULL,NULL),
  ('hh-direction-08','direction',ARRAY['выбор','решен','путь','перемен','направлен','будущее','change','decision','choice','future','path','camino','cambio','decision','futuro','direccion']::text[],'A direction becomes real when it changes the way you live today.','Направление становится реальным, когда меняет твой сегодняшний день.','Un rumbo se vuelve real cuando cambia tu forma de vivir hoy.','editorial',NULL,NULL,NULL),
  ('hh-boundaries-01','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'Your choices are yours; another person''s reactions are not.','Твои решения принадлежат тебе, а чужая реакция — другому.','Tus decisiones te pertenecen; las reacciones ajenas no.','inspired','Epictetus','The Enchiridion (George Long, public-domain translation)','https://www.gutenberg.org/ebooks/10661'),
  ('hh-boundaries-02','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'A kind no can make room for a sincere yes.','Доброе «нет» освобождает место для искреннего «да».','Un no amable abre espacio para un sí sincero.','editorial',NULL,NULL,NULL),
  ('hh-boundaries-03','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'A boundary explains where you stand; it need not attack anyone.','Граница показывает, где ты стоишь; ей не нужно никого атаковать.','Un límite muestra dónde estás; no necesita atacar a nadie.','editorial',NULL,NULL,NULL),
  ('hh-boundaries-04','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'Respect becomes visible when someone hears a refusal.','Уважение становится заметным, когда другой слышит отказ.','El respeto se vuelve visible cuando alguien acepta una negativa.','editorial',NULL,NULL,NULL),
  ('hh-boundaries-05','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'Being available to others should not mean being absent from yourself.','Быть доступным для других не значит отсутствовать для себя.','Estar disponible para otros no significa ausentarte de ti.','editorial',NULL,NULL,NULL),
  ('hh-boundaries-06','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'A clear limit is easier to honor than a silent resentment.','Ясное ограничение легче уважать, чем молчаливую обиду.','Es más fácil respetar un límite claro que un resentimiento callado.','editorial',NULL,NULL,NULL),
  ('hh-boundaries-07','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'You may care deeply without taking responsibility for every emotion.','Можно глубоко заботиться и не отвечать за каждое чужое чувство.','Puedes cuidar profundamente sin asumir la responsabilidad de cada emoción ajena.','editorial',NULL,NULL,NULL),
  ('hh-boundaries-08','boundaries',ARRAY['границ','отказ','нет','манипуляц','контроль','давлен','наруш','отношени','boundaries','no','control','pressure','manipulation','limites','control','presion','abuso']::text[],'The door to closeness works best when it can open and close.','Дверь к близости лучше служит, когда может и открываться, и закрываться.','La puerta de la cercanía funciona mejor cuando puede abrirse y cerrarse.','editorial',NULL,NULL,NULL),
  ('hh-selfworth-01','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'Your considered voice deserves to be heard before the crowd.','Твой обдуманный голос заслуживает быть услышанным раньше шума толпы.','Tu voz reflexiva merece ser escuchada antes que el ruido de la multitud.','inspired','Ralph Waldo Emerson','Essays, First Series (1841)','https://www.gutenberg.org/ebooks/2944'),
  ('hh-selfworth-02','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'You are more than the last opinion someone formed about you.','Ты больше, чем последнее мнение, которое о тебе составили.','Eres más que la última opinión que alguien se formó sobre ti.','editorial',NULL,NULL,NULL),
  ('hh-selfworth-03','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'Worth is not a grade awarded for constant usefulness.','Ценность — не оценка за непрерывную полезность.','El valor personal no es una nota por ser útil sin descanso.','editorial',NULL,NULL,NULL),
  ('hh-selfworth-04','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'Comparison measures distances, not the depth of a person.','Сравнение измеряет расстояния, но не глубину человека.','La comparación mide distancias, no la profundidad de una persona.','editorial',NULL,NULL,NULL),
  ('hh-selfworth-05','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'An imperfect beginning still belongs to a capable person.','Несовершенное начало всё равно может принадлежать способному человеку.','Un comienzo imperfecto también puede ser obra de una persona capaz.','editorial',NULL,NULL,NULL),
  ('hh-selfworth-06','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'Confidence can grow from keeping small promises to yourself.','Уверенность растёт, когда выполняешь небольшие обещания себе.','La confianza puede crecer al cumplirte pequeñas promesas.','editorial',NULL,NULL,NULL),
  ('hh-selfworth-07','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'Your right to be here needs no performance review.','Твоё право быть здесь не требует отчёта о достижениях.','Tu derecho a estar aquí no necesita evaluación de rendimiento.','editorial',NULL,NULL,NULL),
  ('hh-selfworth-08','selfworth',ARRAY['самооценк','ценност','уверенн','стыд','ничтож','достоин','сравнен','self','worth','confidence','shame','esteem','value','confianza','autoestima','vergüenza','valor']::text[],'The mirror tells you how you look, not all you are.','Зеркало показывает твой облик, но не всю твою сущность.','El espejo muestra tu aspecto, no todo lo que eres.','editorial',NULL,NULL,NULL),
  ('hh-loneliness-01','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'Solitude can reveal the quiet thoughts that noise conceals.','Уединение помогает услышать тихие мысли, которые прячет шум.','La soledad elegida puede revelar pensamientos que el ruido oculta.','inspired','Henry David Thoreau','Walden (1854)','https://www.gutenberg.org/ebooks/205'),
  ('hh-loneliness-02','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'Being alone and being abandoned are not the same experience.','Быть одному и быть покинутым — не одно и то же.','Estar a solas y sentirse abandonado no son lo mismo.','editorial',NULL,NULL,NULL),
  ('hh-loneliness-03','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'One trustworthy encounter can matter more than a crowded room.','Одна надёжная встреча может значить больше, чем полный зал.','Un encuentro confiable puede importar más que una sala llena.','editorial',NULL,NULL,NULL),
  ('hh-loneliness-04','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'The heart needs both its own room and an open window.','Сердцу нужны и собственная комната, и открытое окно.','El corazón necesita una habitación propia y una ventana abierta.','editorial',NULL,NULL,NULL),
  ('hh-loneliness-05','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'You can learn to enjoy your company while still longing for connection.','Можно учиться радоваться себе и всё ещё желать близости.','Puedes disfrutar de tu compañía y seguir deseando conexión.','editorial',NULL,NULL,NULL),
  ('hh-loneliness-06','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'A message sent with sincerity is a small bridge across distance.','Искреннее сообщение — маленький мост через расстояние.','Un mensaje sincero es un pequeño puente sobre la distancia.','editorial',NULL,NULL,NULL),
  ('hh-loneliness-07','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'Loneliness is a feeling to meet with care, not a label to wear forever.','Одиночество — чувство, требующее заботы, а не вечный ярлык.','La soledad es una emoción que merece cuidado, no una etiqueta permanente.','editorial',NULL,NULL,NULL),
  ('hh-loneliness-08','loneliness',ARRAY['одиноч','одинок','изолирован','никого','нет','отвержен','solitude','lonely','alone','isolated','loneliness','soledad','solo','aislado']::text[],'Connection often begins with the risk of being seen as you are.','Связь часто начинается с риска показаться таким, какой ты есть.','La conexión suele empezar con el riesgo de mostrarse tal como uno es.','editorial',NULL,NULL,NULL),
  ('hh-grief-01','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'Because all things change, each tender moment deserves attention.','Именно потому, что всё меняется, каждый нежный миг достоин внимания.','Precisamente porque todo cambia, cada instante tierno merece atención.','inspired','Marcus Aurelius','Meditations (George Long, 1862)','https://www.gutenberg.org/ebooks/6920'),
  ('hh-grief-02','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'Grief can be the shape that love takes after an absence.','Горе иногда становится формой любви после утраты.','El duelo puede ser la forma que adopta el amor ante una ausencia.','editorial',NULL,NULL,NULL),
  ('hh-grief-03','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'Remembering does not require living forever in yesterday.','Помнить — не значит навсегда поселиться во вчера.','Recordar no exige vivir para siempre en el ayer.','editorial',NULL,NULL,NULL),
  ('hh-grief-04','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'There is no timetable by which a heart must become quiet.','Нет расписания, по которому сердце обязано успокоиться.','No existe un calendario que obligue al corazón a calmarse.','editorial',NULL,NULL,NULL),
  ('hh-grief-05','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'A memory can ache and nourish us in the same breath.','Воспоминание может одновременно ранить и питать нас.','Un recuerdo puede doler y nutrirnos al mismo tiempo.','editorial',NULL,NULL,NULL),
  ('hh-grief-06','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'You may carry sadness and still welcome a new morning.','Можно нести печаль и всё же встречать новое утро.','Puedes llevar tristeza contigo y aun así recibir una nueva mañana.','editorial',NULL,NULL,NULL),
  ('hh-grief-07','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'What mattered remains part of the story, even when the chapter ends.','То, что было важно, остаётся частью истории после конца главы.','Lo que importó sigue siendo parte de la historia cuando termina el capítulo.','editorial',NULL,NULL,NULL),
  ('hh-grief-08','grief',ARRAY['потер','горе','утрат','смерт','скорб','расстав','прощан','grief','loss','death','mourning','bereave','duelo','perdida','muerte','separacion','tristeza']::text[],'Gentleness with yourself is not forgetting the person you miss.','Бережность к себе — не забвение того, по кому скучаешь.','Ser amable contigo no significa olvidar a quien echas de menos.','editorial',NULL,NULL,NULL),
  ('hh-courage-01','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'Meet the task before you; fear need not cast the deciding vote.','Встреться с делом перед тобой: страху необязательно давать решающий голос.','Enfrenta la tarea presente; el miedo no tiene que emitir el voto decisivo.','inspired','Marcus Aurelius','Meditations (George Long, 1862)','https://www.gutenberg.org/ebooks/6920'),
  ('hh-courage-02','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'Courage is often quieter than the stories told about it.','Мужество часто тише историй, которые о нём рассказывают.','La valentía suele ser más silenciosa que las historias sobre ella.','editorial',NULL,NULL,NULL),
  ('hh-courage-03','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'A brave step may be small enough to fit into today.','Смелый шаг может быть настолько мал, что уместится в сегодня.','Un paso valiente puede ser tan pequeño que quepa en el día de hoy.','editorial',NULL,NULL,NULL),
  ('hh-courage-04','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'The aim is not to erase fear but to make space for choice.','Цель не стереть страх, а освободить место для выбора.','La meta no es borrar el miedo, sino dejar lugar a la elección.','editorial',NULL,NULL,NULL),
  ('hh-courage-05','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'Asking for help may be the most courageous decision in the room.','Попросить о помощи порой самое смелое решение в комнате.','Pedir ayuda puede ser la decisión más valiente de la sala.','editorial',NULL,NULL,NULL),
  ('hh-courage-06','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'It takes strength to start again without pretending nothing happened.','Нужна сила, чтобы начать снова, не делая вид, будто ничего не было.','Hace falta fuerza para comenzar de nuevo sin fingir que nada ocurrió.','editorial',NULL,NULL,NULL),
  ('hh-courage-07','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'Courage can sound like a calm and clear sentence.','Мужество иногда звучит как спокойная и ясная фраза.','La valentía puede sonar como una frase tranquila y clara.','editorial',NULL,NULL,NULL),
  ('hh-courage-08','courage',ARRAY['мужество','смел','решимость','боюсь','риск','отваг','courage','brave','afraid','risk','miedo','valentia','coraje','atreverse']::text[],'Let the next honest act be larger than the imagined audience.','Пусть следующий честный поступок будет важнее воображаемых зрителей.','Que el siguiente acto sincero pese más que el público imaginado.','editorial',NULL,NULL,NULL),
  ('hh-acceptance-01','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'What the mind rehearses becomes the path it knows best.','То, что разум повторяет, становится самой знакомой ему дорогой.','Lo que la mente repite se convierte en el camino que mejor conoce.','inspired','Dhammapada (traditional Buddhist text)','Dhammapada (F. Max Müller translation)','https://www.gutenberg.org/ebooks/2017'),
  ('hh-acceptance-02','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'Accepting what happened does not mean calling it good.','Признать случившееся — не значит объявить его хорошим.','Aceptar lo ocurrido no significa decir que fue bueno.','editorial',NULL,NULL,NULL),
  ('hh-acceptance-03','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'You may release the argument without excusing the harm.','Можно прекратить внутренний спор, не оправдывая причинённый вред.','Puedes dejar la discusión interior sin justificar el daño.','editorial',NULL,NULL,NULL),
  ('hh-acceptance-04','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'An emotion deserves attention; it does not always deserve the steering wheel.','Чувство заслуживает внимания, но не всегда права вести машину.','Una emoción merece atención, pero no siempre el volante.','editorial',NULL,NULL,NULL),
  ('hh-acceptance-05','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'Anger points to a wound; it need not choose every response.','Гнев указывает на рану, но не обязан выбирать каждый ответ.','La ira señala una herida, pero no tiene que elegir cada respuesta.','editorial',NULL,NULL,NULL),
  ('hh-acceptance-06','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'Letting go often happens in layers, not in one heroic moment.','Отпускание часто происходит слоями, а не одним героическим рывком.','Soltar suele ocurrir por capas, no en un único momento heroico.','editorial',NULL,NULL,NULL),
  ('hh-acceptance-07','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'Peace is not agreement with the past; it is room for the present.','Покой — не согласие с прошлым, а пространство для настоящего.','La paz no es estar de acuerdo con el pasado, sino dar espacio al presente.','editorial',NULL,NULL,NULL),
  ('hh-acceptance-08','acceptance',ARRAY['принятие','злость','гнев','завист','обид','отпустить','сожал','прием','anger','resentment','acceptance','let','go','accept','rabia','ira','aceptar','soltar','resentimiento']::text[],'You can forgive yourself for learning something late.','Можно простить себе то, что важное понимание пришло поздно.','Puedes perdonarte por haber aprendido algo tarde.','editorial',NULL,NULL,NULL),
  ('hh-love-01','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'Love calls for breathing room, not ownership.','Любви нужно пространство для дыхания, а не право собственности.','El amor necesita espacio para respirar, no propiedad.','inspired','Kahlil Gibran','The Prophet (1923)','https://www.gutenberg.org/ebooks/58585'),
  ('hh-love-02','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'Tenderness makes room for truth without turning it into a weapon.','Нежность оставляет место правде, не превращая её в оружие.','La ternura hace lugar a la verdad sin convertirla en arma.','editorial',NULL,NULL,NULL),
  ('hh-love-03','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'Passion grows safer when both people can speak freely.','Страсть становится безопаснее, когда оба могут говорить свободно.','La pasión es más segura cuando ambos pueden hablar libremente.','editorial',NULL,NULL,NULL),
  ('hh-love-04','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'To love is also to wonder who the other person is becoming.','Любить — значит интересоваться, кем становится другой человек.','Amar también es preguntarse en quién se está convirtiendo el otro.','editorial',NULL,NULL,NULL),
  ('hh-love-05','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'Affection is strongest when it does not demand a disguise.','Привязанность сильнее там, где не требуется маска.','El afecto es más fuerte cuando no exige disfraces.','editorial',NULL,NULL,NULL),
  ('hh-love-06','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'A warm touch means more when permission is part of it.','Тёплое прикосновение значит больше, когда в нём есть согласие.','Un contacto cálido vale más cuando incluye consentimiento.','editorial',NULL,NULL,NULL),
  ('hh-love-07','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'Love can be generous without promising to carry every burden.','Любовь может быть щедрой, не обещая нести каждую тяжесть.','El amor puede ser generoso sin prometer cargar con todo.','editorial',NULL,NULL,NULL),
  ('hh-love-08','love',ARRAY['любов','романтик','сердц','влюблен','ревност','страст','нежност','love','romance','jealous','affection','amor','enamor','cariño','pasion','celos']::text[],'A loving bond offers both shelter and a view of the open sky.','Любящая связь даёт и укрытие, и вид на открытое небо.','Un vínculo amoroso ofrece refugio y una vista del cielo abierto.','editorial',NULL,NULL,NULL),
  ('hh-time-01','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'A day postponed cannot be stored for a later season.','Отложенный день нельзя спрятать до более подходящего сезона.','Un día aplazado no puede guardarse para otra estación.','inspired','Seneca','Moral Letters to Lucilius','https://senecaletters.com/en/about'),
  ('hh-time-02','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'Your calendar quietly reveals what your choices protect.','Календарь тихо показывает, что защищают твои решения.','Tu calendario revela en silencio aquello que protegen tus decisiones.','editorial',NULL,NULL,NULL),
  ('hh-time-03','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'A little time given wholly can be richer than many distracted hours.','Немного времени с полным вниманием богаче многих рассеянных часов.','Un rato de atención plena puede valer más que muchas horas dispersas.','editorial',NULL,NULL,NULL),
  ('hh-time-04','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'The perfect moment is often a story that delays a real one.','Идеальный момент нередко оказывается историей, мешающей реальному.','El momento perfecto suele ser una historia que retrasa uno real.','editorial',NULL,NULL,NULL),
  ('hh-time-05','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'It is not too late to make this ordinary afternoon matter.','Ещё не поздно сделать этот обычный день значимым.','No es tarde para dar valor a esta tarde corriente.','editorial',NULL,NULL,NULL),
  ('hh-time-06','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'Rest is not time stolen from life; it is life being lived.','Отдых — не украденное у жизни время, а сама проживаемая жизнь.','Descansar no es robarle tiempo a la vida; es vivirla.','editorial',NULL,NULL,NULL),
  ('hh-time-07','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'Every yes spends a little of the finite attention you possess.','Каждое «да» тратит частицу твоего конечного внимания.','Cada sí gasta una parte de tu atención limitada.','editorial',NULL,NULL,NULL),
  ('hh-time-08','time',ARRAY['время','откладываю','прокрастинац','успеть','возраст','поздно','жизнь','time','procrastinat','delay','aging','late','tiempo','aplazar','procrastinar','edad','tarde']::text[],'Do not wait to deserve the hour already in your hands.','Не жди, пока заслужишь час, который уже у тебя в руках.','No esperes merecerte la hora que ya tienes entre manos.','editorial',NULL,NULL,NULL),
  ('hh-purpose-01','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'Meaning is tested in how we inhabit ordinary days.','Смысл проверяется тем, как мы проживаем обычные дни.','El sentido se prueba en la forma en que habitamos los días corrientes.','inspired','Michel de Montaigne','Essays (Charles Cotton translation)','https://www.gutenberg.org/ebooks/3600'),
  ('hh-purpose-02','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'A calling does not always arrive as a thunderclap.','Призвание не всегда приходит раскатом грома.','Una vocación no siempre llega como un trueno.','editorial',NULL,NULL,NULL),
  ('hh-purpose-03','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'What you return to with care may reveal what matters.','То, к чему ты заботливо возвращаешься, часто указывает на главное.','Aquello a lo que vuelves con cuidado puede revelar lo que importa.','editorial',NULL,NULL,NULL),
  ('hh-purpose-04','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'A meaningful life may contain many small useful chapters.','Осмысленная жизнь может состоять из множества небольших полезных глав.','Una vida con sentido puede contener muchos capítulos pequeños y útiles.','editorial',NULL,NULL,NULL),
  ('hh-purpose-05','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'The question of purpose grows clearer in conversation with action.','Вопрос о предназначении проясняется в разговоре с действием.','La pregunta por el propósito se aclara al conversar con la acción.','editorial',NULL,NULL,NULL),
  ('hh-purpose-06','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'You are allowed to discover a new meaning at a new age.','Ты можешь открыть новый смысл в любом возрасте.','Puedes descubrir un nuevo sentido en cualquier edad.','editorial',NULL,NULL,NULL),
  ('hh-purpose-07','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'Purpose is a direction of care, not necessarily a title.','Предназначение — направление заботы, а не обязательно должность.','El propósito es una dirección del cuidado, no necesariamente un título.','editorial',NULL,NULL,NULL),
  ('hh-purpose-08','purpose',ARRAY['смысл','призвание','зачем','предназнач','мисси','духовн','purpose','meaning','calling','destiny','sentido','proposito','vocacion','mision','espiritual']::text[],'A life can matter without being spectacular.','Жизнь может иметь значение, даже не будучи зрелищной.','Una vida puede importar sin ser espectacular.','editorial',NULL,NULL,NULL),
  ('hh-gratitude-01','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'What we already have becomes clearer when we learn to notice it.','То, что у нас уже есть, становится яснее, когда мы учимся замечать.','Lo que ya tenemos se vuelve más claro cuando aprendemos a verlo.','inspired','Seneca','Moral Letters to Lucilius','https://senecaletters.com/en/about'),
  ('hh-gratitude-02','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'Gratitude is not a demand to ignore what hurts.','Благодарность не требует закрывать глаза на боль.','La gratitud no exige ignorar lo que duele.','editorial',NULL,NULL,NULL),
  ('hh-gratitude-03','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'One ordinary kindness can brighten a complicated day.','Одна простая доброта способна осветить сложный день.','Un gesto amable y cotidiano puede iluminar un día complicado.','editorial',NULL,NULL,NULL),
  ('hh-gratitude-04','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'Joy sometimes enters quietly through attention to details.','Радость иногда входит тихо — через внимание к деталям.','La alegría a veces entra en silencio, por la atención a los detalles.','editorial',NULL,NULL,NULL),
  ('hh-gratitude-05','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'It is possible to appreciate today while still hoping for change.','Можно ценить сегодня и одновременно надеяться на перемены.','Puedes valorar el presente y a la vez desear cambios.','editorial',NULL,NULL,NULL),
  ('hh-gratitude-06','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'A thank-you becomes deeper when it names something specific.','«Спасибо» становится глубже, когда называет что-то конкретное.','Un gracias es más profundo cuando nombra algo concreto.','editorial',NULL,NULL,NULL),
  ('hh-gratitude-07','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'Enough is a gentle word that endless comparison cannot pronounce.','«Достаточно» — мягкое слово, незнакомое бесконечному сравнению.','Suficiente es una palabra amable que la comparación infinita no sabe decir.','editorial',NULL,NULL,NULL),
  ('hh-gratitude-08','gratitude',ARRAY['благодарн','радост','счастье','благодарю','ценю','достаток','довольн','gratitude','grateful','joy','happy','thanks','gratitud','agradecid','alegria','felicidad']::text[],'The small gift of being present costs little and offers much.','Небольшой дар присутствия почти ничего не стоит и многое даёт.','El pequeño regalo de estar presente cuesta poco y ofrece mucho.','editorial',NULL,NULL,NULL),
  ('hh-creativity-01','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'An original idea begins when you trust what you truly see.','Своя идея начинается с доверия к тому, что ты действительно видишь.','Una idea propia nace cuando confías en lo que realmente ves.','inspired','Ralph Waldo Emerson','Essays, First Series (1841)','https://www.gutenberg.org/ebooks/2944'),
  ('hh-creativity-02','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'Creativity needs permission to make an awkward first draft.','Творчеству нужно разрешение на неловкий первый черновик.','La creatividad necesita permiso para hacer un primer borrador torpe.','editorial',NULL,NULL,NULL),
  ('hh-creativity-03','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'An empty page is a doorway, not a judgment.','Пустая страница — это дверь, а не приговор.','Una página en blanco es una puerta, no un juicio.','editorial',NULL,NULL,NULL),
  ('hh-creativity-04','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'The curious mind gathers seeds before it knows the garden.','Любопытный ум собирает семена ещё до того, как увидит сад.','La mente curiosa recoge semillas antes de conocer el jardín.','editorial',NULL,NULL,NULL),
  ('hh-creativity-05','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'Play is often the workshop where serious ideas begin.','Игра часто становится мастерской серьёзных идей.','El juego suele ser el taller donde nacen ideas serias.','editorial',NULL,NULL,NULL),
  ('hh-creativity-06','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'Your voice becomes clearer through use, not through hiding.','Собственный голос становится яснее в действии, а не в укрытии.','Tu propia voz se aclara al usarla, no al esconderla.','editorial',NULL,NULL,NULL),
  ('hh-creativity-07','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'A useful idea may start as a question nobody answered yet.','Полезная идея может начаться с вопроса, на который пока никто не ответил.','Una idea útil puede nacer de una pregunta aún sin respuesta.','editorial',NULL,NULL,NULL),
  ('hh-creativity-08','creativity',ARRAY['творчеств','вдохновлен','искусств','рисунок','идея','создавать','писать','придум','creative','inspirat','art','write','design','creatividad','inspiracion','arte','pintar','escribir','idea']::text[],'Finish something small so the next possibility has room to grow.','Заверши что-то небольшое, чтобы у новой возможности появилось место.','Termina algo pequeño para dejar espacio a la siguiente posibilidad.','editorial',NULL,NULL,NULL)
