-- Curated public aphorisms for Ideas (EN/RU/ES), sourced from data/ideas-aphorisms.json.
-- All texts are authored editorial wording; inspired entries are NOT verbatim quotations.
-- No client question is inserted or logged in this database.
BEGIN;
CREATE TABLE IF NOT EXISTS public.hh_ideas_aphorisms (
  id text PRIMARY KEY,
  topic text NOT NULL,
  keywords text[] NOT NULL DEFAULT '{}',
  text_en text NOT NULL CHECK (char_length(text_en) >= 20),
  text_ru text NOT NULL CHECK (char_length(text_ru) >= 20),
  text_es text NOT NULL CHECK (char_length(text_es) >= 20),
  kind text NOT NULL CHECK (kind IN ('editorial','inspired')),
  source_author text,
  source_work text,
  source_url text,
  is_published boolean NOT NULL DEFAULT true,
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT hh_ideas_inspired_source CHECK (kind <> 'inspired' OR (source_author IS NOT NULL AND source_url IS NOT NULL))
);
ALTER TABLE public.hh_ideas_aphorisms ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS hh_ideas_public_read_published ON public.hh_ideas_aphorisms;
CREATE POLICY hh_ideas_public_read_published ON public.hh_ideas_aphorisms
  FOR SELECT TO anon, authenticated USING (is_published = true);
REVOKE ALL ON public.hh_ideas_aphorisms FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.hh_ideas_aphorisms TO anon, authenticated;
CREATE INDEX IF NOT EXISTS hh_ideas_topic_published_idx ON public.hh_ideas_aphorisms(topic) WHERE is_published;
-- Initial reviewed catalog; re-seeding on another instance is idempotent.
ON CONFLICT (id) DO UPDATE SET
 topic=EXCLUDED.topic, keywords=EXCLUDED.keywords,
 text_en=EXCLUDED.text_en, text_ru=EXCLUDED.text_ru, text_es=EXCLUDED.text_es,
 kind=EXCLUDED.kind, source_author=EXCLUDED.source_author,
 source_work=EXCLUDED.source_work, source_url=EXCLUDED.source_url,
 updated_at=now();
COMMIT;
